#!/usr/bin/env python3
"""Build a standalone Russian technical report from validated NEW measurements."""
import argparse
import json
import re
import subprocess
from pathlib import Path
import numpy as np
import pandas as pd
from analyze import HERE,ROOT,DEST,NEW,CONTROL,LABELS,gm
from run_all import digest

SHORT=dict(zip(NEW,['Boundary','Selective','Delta','Policy']))
def num(x,n=2):return '—' if pd.isna(x) else f'{x:.{n}f}'
def table(headers,rows):
    def cell(x):return str(x).replace('|',r'\|').replace('\n',' ')
    return '| '+' | '.join(map(cell,headers))+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(cell(v) for v in row)+' |' for row in rows)
def figure(name,caption,width='96%'):
    return f'![{caption}](figures/{name}.png){{width={width}}}'

def main(directory):
    directory=directory.resolve();ad=directory/'analysis';a=json.loads((ad/'analysis.json').read_text());assert a['status']=='passed'
    assert a['analysis_source_sha256']==digest(HERE/'analyze.py')
    for name,sha in a['tables_sha256'].items():assert digest(ad/name)==sha
    for name,sha in json.loads((ad/'figures.json').read_text()).items():assert digest(ROOT/name)==sha
    manifest=json.loads((HERE/'frozen/manifest.json').read_text());experiment=json.loads((directory/'experiment.json').read_text())
    summary=pd.read_csv(ad/'summary.csv');metrics=pd.read_csv(ad/'case_metrics.csv');pairs=pd.read_csv(ad/'paired_cases.csv')
    maps=pd.read_csv(ad/'map_pairs.csv');families=pd.read_csv(ad/'family_pairs.csv');work=pd.read_csv(ad/'work.csv');latency=pd.read_csv(ad/'latency.csv')
    ep=pd.read_csv(ad/'episode_metrics.csv');points=pd.read_csv(ad/'navigation_points.csv')
    completion_controls=pd.read_csv(ad/'completion_vs_controls.csv')
    out=[];add=out.append
    add('# Результат и границы вывода')
    add(f"Реализованы четыре точных исследовательских варианта MPGAA*: Boundary, Selective, Delta и Policy. В новой серии выполнено **{a['timed_runs']:,} временных прогонов**, **{a['memory_runs']:,} отдельных прогонов памяти**, **{a['timed_planner_calls']:,} измеренных вызовов** на **{a['scenarios']} конфигурациях**. Ни один завершённый ответ не разошёлся с точным контролем более чем на $10^{{-6}}$. На небольших динамических картах выполнено {a['independent_dijkstra_comparisons']:,} сравнений с независимым Дейкстрой; ASan/UBSan пройдены. Бюджетные остановки сохранены: **{a['capped_calls']} вызовов**.")
    add('Названия обозначают проверяемые инженерные сочетания известных механизмов. Внешний приоритет и литературная новизна здесь не установлены. Исходный MPGAA* и прежние алгоритмы репозитория не изменены; у четырёх новых методов общий код поиска и обучения. Времена всех контролей измерены заново теми же бинарниками и на той же машине, без подмешивания старых секунд.')
    statuses=pd.read_csv(ad/'statuses.csv');capped=statuses[statuses.status.isin(['capped','skipped_after_cap'])].groupby('method').runs.sum()
    add('Остановленные по лимиту эпизоды в этой серии: '+(', '.join(f'{LABELS.get(method,method)} — {int(count)} временных повторов' for method,count in capped.items()) or 'нет')+'. Остальные недостигнутые цели навигации следует отличать от остановки вычисления: корректное доказательство отсутствия пути по текущей карте знаний не является достижением цели.')
    rows=[]
    for method in NEW:
        own=metrics[metrics.method.eq(method)];p=pairs[pairs.method.eq(method)&pairs.baseline.eq('best_control')]
        only=completion_controls[completion_controls.method.eq(method)]
        rows.append([SHORT[method],f'{int(own.complete.sum())}/{len(own)}',num(gm(p.episode_speedup)),f'{int(p.episode_speedup.ge(1.1).sum())}/{int(p.episode_speedup.notna().sum())}',num(gm(p.memory_ratio)),int(only.candidate_only.sum())])
    add(table(['Метод','Завершено','Эпизод ×','Выигрыш от 10%','Heap ×','Только кандидат'],rows))
    add('В этой обзорной таблице baseline — самый быстрый по полному эпизоду **завершившийся** контроль в каждой конфигурации из LBA*, LBA* reuse, MPGAA*, MD-A*, Boundary-Mesh и, на grid8, Octile A* reuse. Контроль выбирается после замера, поэтому это описательная огибающая сильных соперников. Отношения агрегированы геометрическим средним по общим завершённым конфигурациям; строки имеют разные допустимые множества. «Heap ×» означает пик контроля / пик кандидата. В replay завершение включает корректный ответ «пути нет»; в миссии означает достижение цели. Доли завершения относятся ко всем конфигурациям кандидата, а не только к парам. «Только кандидат» считает завершённые им конфигурации, в которых не завершился ни один контроль; для них ускорение не вычисляется. Полная разметка, включая обратные случаи, сохранена в completion_vs_controls.csv.')
    p=pairs[pairs.method.isin(NEW)&pairs.baseline.eq('best_control')]
    if (p.episode_speedup.dropna()<1).any() or (~metrics[metrics.method.isin(NEW)].complete).any():
        add('**Универсальное преимущество четырёх вариантов не подтверждено.** Есть проигрыши сильным контролям или незавершённые конфигурации. Ни большое сокращение отдельного счётчика, ни ускорение online-части сами по себе не означают выигрыш полного эпизода. Дальше приведены отдельные модели, нагрузки, карты, полнота и абляции.')
    replay=summary[summary.cohort.eq('replay')&summary.control.eq('car16')&summary.baseline.eq('mpgaa')].set_index('method')
    b=replay.loc['boundary_mpgaa'];d=replay.loc['delta_mpgaa']
    add(f"На car16 replay Boundary даёт **{num(b.episode_speedup)}× по полному эпизоду и {num(b.online_speedup)}× по ремонту** относительно MPGAA* на {int(b.paired)}/{int(b.configurations)} конфигурациях. Его пик heap в {num(b.memory_ratio)} раза меньше. Это полезный результат замены вычисления коллизий и кеша, при сохранённых раскрытиях поиска. У Delta online-отношение {num(d.online_speedup)}× сочетается с полным отношением {num(d.episode_speedup)}× и пиком heap примерно в {num(1/d.memory_ratio)} раза больше MPGAA*: начальная материализация и подписки меняют практический вывод. На одноклеточном grid8 возможности разделения длинных трасс отсутствуют; результаты этой модели рассмотрены отдельно.")
    add(figure('episode_speedup','Полный эпизод: отдельные когорты и модели. Слева baseline MPGAA*, справа огибающая сильных контролей. Показано геометрическое среднее только на общих завершённых конфигурациях; полнота приведена отдельно. Значение больше единицы выгодно кандидату.'))
    add('# Модель и общий инвариант MPGAA*')
    add(r'''Состояние $u=(i,j,\theta)$ — граница примитива. Примитив $p$ имеет исходные положительную стоимость $c(p)$, конечное состояние $v=\operatorname{end}(u,p)$ и упорядоченную трассу клеток. Для car16 сохранены 16 ориентаций, направленные движения и исходные double-стоимости; grid8 имеет одну ориентацию, восемь одноклеточных движений, стоимости $1$ и $\sqrt 2$. Как и в прежней модели grid8, диагональ проверяет конечную клетку и не добавляет нового запрета на срезание углов. Цель фиксирована в течение эпизода.

MPGAA* хранит обученную нижнюю оценку $h$, один указатель продолжения `next` и кеш допустимости переходов. Исходная оценка $h_0(u)$ — евклидово расстояние до цели. Из условия $c(p)\geq\|u-v\|_2$ следует согласованность $h_0$. До очередного поиска поддерживается

$$0\le h(u)\le d^*(u,t),\qquad h(u)\le c(u,v)+h(v)$$

на допустимых переходах. Добавление препятствия не нарушает допустимость старой оценки. Освобождение может её нарушить: все варианты сначала выявляют вновь разрешённые переходы, снижают затронутые $h(u)$ и распространяют снижения по предшественникам очередью MPGAA*. Поэтому в результатах отдельно учитываются уведомления и `heuristic_pops`.

A* заканчивается в цели или в состоянии, у которого существует допустимая tight-цепочка `next` до цели. Её стоимость равна $h(u)$. После решения стоимости $C$ для раскрытых состояний обновляется $h(u)\gets\max(h(u),C-g(u))$. Порядок кандидатов, tie breaking по большему $g$, исходные примитивы и бюджет раскрытий сохранены. На 1 080 динамических снимках Boundary дополнительно совпал с исходным MPGAA* по числу раскрытий.''')
    add('# Четыре реализации')
    add('## Boundary-MPGAA*: проверять общий префикс один раз')
    add(r'''`MeshIndex` строит отдельное дерево для каждой исходной ориентации. Узел соответствует префиксу **исходной упорядоченной трассы**, содержит относительную клетку, потомков, завершившиеся примитивы и список всех примитивов ветви. Совпадение геометрического смещения без совпадения предыдущих клеток не сливает ветви.

При раскрытии граничного состояния обход дерева проверяет общие клетки один раз и получает маску разрешённых примитивов. Препятствие закрывает все завершения ниже узла. Маска кешируется у материализованного состояния; уведомления по прежним геометрическим группам инвалидируют её после изменений. Поиск остаётся на границах примитивов: промежуточные mesh-узлы не становятся вершинами OPEN.

**Сохранение графа.** Лист или терминал дерева соответствует ровно исходной трассе примитива. Он разрешён тогда и только тогда, когда свободны все её проверяемые клетки. Стоимость перехода и его конечное состояние не меняются; значит, меняется только стоимость вычисления допустимости, а множество путей и их стоимости сохраняются.

**Цена.** Вместо суммы длин всех трасс посещается достигнутая часть дерева. Дополнительная память — маски для материализованных состояний и общий шаблон. При одноклеточных grid8-примитивах почти нет полезного общего префикса; накладные расходы могут преобладать. Пакетная проверка также может затратить работу на примитивы, которые обычный поиск отбросил бы ещё до проверки коллизии.''')
    add('## Selective-Mesh-MPGAA*: отсечение до коллизий')
    add(r'''Ветвь $q$ содержит множество примитивов $P(q)$. До её проверки вычисляется

$$B(u,q)=\min_{p\in P(q)}\{c(p)+h(\operatorname{end}(u,p))\}.$$

Пусть $U$ — стоимость **допустимого** полного пути. Если $g(u)+B(u,q)>U$, ветвь не может дать улучшение и её клетки не проверяются. В коде применён консервативный запас $8\,\mathrm{EPS}$: ветвь отсекается только при `g + B >= U + 8*EPS`; равные варианты сохраняются. Отсечённая ветвь не записывается как заблокированная: ещё не проверенные флаги остаются неизвестными, а ранее вычисленные коллизионные флаги сохраняются.

Верхнюю границу даёт допустимый суффикс ранее найденного пути либо соединение уже достигнутого префикса с проверенным продолжением MPGAA*. Индекс клеток пути отслеживает его повреждения. Освобождения не нарушают допустимость этого пути, но могут сделать его неоптимальным; поэтому они сначала ремонтируют $h$, и сохранённый путь используется только как верхняя граница.

**Безопасность отсечения.** Для любого продолжения через $p\in P(q)$ его стоимость не меньше $g(u)+c(p)+h(\operatorname{end}(u,p))\geq g(u)+B(u,q)$. При указанном условии оно хуже существующего допустимого решения. Очередь и сохранённый incumbent обрабатываются вместе; удаление всех неконкурентных кандидатов не превращает допустимый incumbent в ответ «пути нет».

**Цена и абляции.** Нижняя оценка ветви сама требует перебора её концов и чтения $h$. Без верхней границы отсечение не применяется. `selective_no_prune` сохраняет тот же incumbent и ту же структуру поиска, отключая только проверки границ ветвей. `selective_geom` подставляет в $B$ исходную $h_0$, при этом основной A* по-прежнему использует обученную $h$. Эти два контроля отделяют эффект отсечения от хранения пути и вклад обученных оценок от геометрических.''')
    add('## Delta-Mesh-MPGAA*: события действительной допустимости')
    add(r'''Для каждого материализованного граничного состояния Delta сохраняет достигнутые узлы дерева. Обратный индекс связывает клетку с парами «состояние, узел». В свободной части дерева регистрируются все достигнутые клетки; первый блокирующий узел также регистрируется и служит **свидетелем** для всех своих потомков. Потомки за этим препятствием пока не подписываются.

При пакете правок сначала обновляется карта, затем из индекса извлекаются затронутые узлы. Изменённый предок поглощает изменённых потомков того же пакета. Только соответствующие поддеревья пересчитываются; старые подписки снимаются, новые регистрируются. Затем прежняя и новая маски сравниваются: в обслуживание MPGAA* поступают только переходы с изменившейся итоговой допустимостью. Блокировка инвалидирует выбранное продолжение; вновь разрешённый переход может запустить снижение эвристики.

**Полнота уведомлений.** Если разрешённый переход стал запрещённым, новая блокировка лежит в его ранее достигнутом префиксе, значит, имеет подписку. Если запрещённый переход стал разрешённым, прежний первый блокирующий узел обязательно открылся и имеет подписку-свидетель; обход обнаружит новое состояние оставшейся трассы. Правки за остающимся заблокированным свидетелем не меняют допустимость перехода. Для каждого раскрываемого состояния до обучения материализуются **все** исходящие примитивы, включая доминируемые поиском; поэтому вновь разрешённый переход из обученного состояния не теряется. У ещё не материализованного состояния нет обученного $h$ и сохранённого продолжения; при первом обращении оно проверяется по текущей карте.

**Цена.** Выигрыш в доставке уведомлений оплачивается обратным индексом, снятием подписок и пересчётом поддеревьев. Время не равно только числу `validity_flips`: дополнительно просматривается маска каждого затронутого состояния. В реализации массив активности выделен для всего шаблонного дерева каждого материализованного состояния, включая недостигнутые узлы. Поэтому память включает не только действующие подписки. В открытой области длинных примитивов их число тоже может быть большим.''')
    add('## Policy-Mesh-MPGAA*: граф оптимальных продолжений')
    add(r'''После решения Policy сохраняет у раскрытых состояний и состояний пути несколько разрешённых переходов, удовлетворяющих

$$h(u)=c(u,v)+h(v).$$

Перед раскрытием очередной вершины выполняется DFS по этим альтернативам и текущему `next`, с мемоизацией внутри запроса. При обходе заново проверяются актуальная tight-связь и допустимость перехода по общей mesh-маске. Успешная цепочка устанавливает выбранные указатели `next`; при неуспехе запускается обычное продолжение MPGAA*. Неуспех DFS **не** доказывает отсутствие пути: сохранённый граф может быть неполным.

**Сертификат оптимальности.** Для найденной цепочки $u_0=s,\ldots,u_k=t$ суммирование tight-равенств даёт

$$\sum_{i=0}^{k-1}c(u_i,u_{i+1})=h(s)-h(t)=h(s).$$

Путь допустим, а $h$ — нижняя оценка; значит, его стоимость оптимальна. Положительные стоимости исключают tight-циклы в точной арифметике. Реализация также явно отслеживает активные состояния DFS и проверяет реконструируемые цепочки на цикл.

Обычный MPGAA* уже присоединяет поиск к **одному** сохранённому продолжению. Новый механизм здесь — выбор среди нескольких tight-альтернатив до очередного раскрытия. Это ленивый обход сохранённого графа, а не отдельный полностью динамический алгоритм связности. Дополнительные альтернативы и DFS могут стоить дороже нового A*.''')
    add('## Основные дополнительные затраты')
    add(r'''Пусть $R$ — число материализованных граничных состояний, $d$ — максимальное число исходящих примитивов, $N_T$ — максимальное число узлов шаблонного дерева одной ориентации, $T$ — число достигнутых пар «состояние, узел префикса», $E_P$ — число сохранённых tight-альтернатив. В таблице опущены общие структуры MPGAA* и неизменный общий шаблон.''')
    add(table(['Механизм','Дополнительная память','Дополнительная работа'],[
        ['Маски Boundary',r'$O(Rd)$','Достигнутая часть дерева вместо отдельных трасс'],
        ['Границы Selective',r'$O(Rd)$ и индекс пути',r'До $\sum_q |P(q)|$ оценок концов при одном обходе'],
        ['Подписки Delta',r'$O(R(N_T+d)+T)$','Массив активности, подписки, обход поддеревьев и сравнение масок'],
        ['Альтернативы Policy',r'$O(Rd+E_P)$','DFS по достигнутому графу альтернатив с мемоизацией']]))
    add('Это оценки структуры реализации, а не доказательство ускорения относительно MPGAA*. Например, сокращение уведомлений Delta может сопровождаться большой ценой хранения подписок, а оценка ветвей Selective — требовать больше обращений к эвристике, чем сэкономлено дешёвых чтений клеток.')
    add('# Протокол измерения')
    add(table(['Когорта','Конфигураций','Назначение'],[
        ['Replay car16','90','Шесть карт; on/off-path, churn, раскрытие, история'],
        ['Replay grid8','96','Четыре карты 50×50; плотности 10–40%, k/cr'],
        ['Прежние миссии','40','Движение по неизвестной карте, собственные траектории'],
        ['Навигация с динамикой','128','16 карт × 2 корня × 4 опорные точки'],
        ['Новое раскрытие car16','24','6 карт × 2 корня × 2 радиуса']]))
